                // If init is called on a list of elements, an array of instances is returned
                const collapsibleInstanceOrInstances = M.Collapsible.init(document.getElementById('outerCollapsible'), collapsibleOptions);

                const userSettings = {
                    elasticsearchFilterManager: {},
                    htmlInputModel: { clearFilterSelectboxAfterUse: true },
                    graphModel: { outerWrapperSelector: "#graphicsWrapper" },
                    profilingController: {
                        fieldChooserSelector: "#dataExplorerDataFields",
                        enableAdvancedDimensionQueryOption: true
                    },
                    elasticsearchModel: {
                        elasticsearchIndex: "spotify_tracks"
                    }
                };

                // Add (global) elasticsearch settings. Note that variable response contains the whole
                // response structure, while response.json() extracts the contained json data
                fetch('config/baseConfig.json')
                    .then((response) => response.json())
                    .then((data) => {
                        // Merge our settings in this file with the settings from default config file
                        const options = BaseUtils.mergeTwoObjectsTwoLevelsDeep( data, userSettings );

                        //const options = BaseUtils.mergeTwoObjectsTwoLevelsDeep( userSettings, data );
                        I18nTranslator.init( options, ['de','en'] )
                            .then( () => {
                                I18nTranslator.switchToDefaultLanguage('en');
                                I18nTranslator.translatePageTo();
                                new ProfilingController( new SpotifyExplorerConfigurator().init(), options ).init();
                            });
